class BytesIOCopy:
    """A binary buffer, backed by a real file, that copies everything
    written to it to another buffer.

    Being backed by a real file (rather than :class:`io.BytesIO`) means
    the buffer has a real file descriptor, so it can be used as the
    ``stdout``/``stderr`` of :func:`subprocess.run` and similar APIs.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3
        Backed by a temporary file instead of :class:`io.BytesIO` so it
        supports ``fileno()``.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def fileno(self) -> int:
        return self._file.fileno()

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

