class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3
        Supports ``fileno()`` so the buffer can be used as ``stdout``/
        ``stderr`` for :func:`subprocess.run` and similar APIs. The real
        file descriptor is only created lazily, the first time it's
        needed, so plain in-memory usage is unaffected.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._file: t.IO[bytes] | None = None

    def flush(self) -> None:
        super().flush()
        if self._file is not None:
            self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        if self._file is not None:
            self._file.write(b)
            return super().write(b)
        return super().write(b)

    def fileno(self) -> int:
        if self._file is None:
            # Lazily back this buffer with a real file so callers that
            # need a real file descriptor (e.g. subprocess.run) work,
            # while everyone else keeps using the fast in-memory buffer.
            self._file = tempfile.TemporaryFile()
            self._file.write(super().getvalue())
            self._file.flush()
        return self._file.fileno()

    def getvalue(self) -> bytes:
        if self._file is not None:
            pos = self._file.tell()
            self._file.seek(0)
            data = self._file.read()
            self._file.seek(pos)
            return data
        return super().getvalue()

    def close(self) -> None:
        if self._file is not None:
            self._file.close()
        super().close()

